-- Slice 3 regression test: CSS absolute positioning on a fixed-layout page.
--
-- Renders fxl_positioned.epub (generated by crengine's
-- make_fixedlayout_test_epub.py) at its native viewport size, so the page maps
-- 1:1 to the output buffer (no scaling), and asserts that each absolutely
-- positioned coloured box lands at the pixel coordinates its CSS places it:
--   #green  top:0  left:0   100% x 40px   -> full-width band along the top
--   #red    top:100 left:50 200  x 150    -> anchored by top/left
--   #inner  top:20  left:20 40   x 40      -> nested, relative to #red (its
--                                            positioned ancestor), not the page
--   #blue   bottom:0 right:0 120 x 90      -> anchored by bottom/right
-- A point in the middle of the page (covered by no box) must stay the white
-- background.
local DATA = "spec/front/unit/data/fixedlayout/"
local VP_W, VP_H = 800, 1200

describe("Fixed-layout CSS absolute positioning", function()
    local DocumentRegistry, Blitbuffer

    setup(function()
        require("commonrequire")
        DocumentRegistry = require("document/documentregistry")
        Blitbuffer = require("ffi/blitbuffer")
    end)

    -- Render page `pageno` of the book to an RGB32 buffer at viewport size.
    local function render(pageno)
        local doc = DocumentRegistry:openDocument(DATA .. "fxl_positioned.epub")
        assert.truthy(doc, "could not open fxl_positioned.epub")
        assert.is_true(doc:loadDocument())
        assert.are.equal(1, doc:getFixedLayoutMode())
        doc.render_color = true
        doc:setViewDimen({ w = VP_W, h = VP_H })
        doc:render()
        local bb = Blitbuffer.new(VP_W, VP_H, Blitbuffer.TYPE_BBRGB32)
        bb:fill(Blitbuffer.COLOR_BLACK) -- a colour no box uses, so a miss is obvious
        doc:drawCurrentViewByPage(bb, 0, 0, { x = 0, y = 0, w = VP_W, h = VP_H }, pageno)
        return doc, bb
    end

    -- Assert the pixel at (x,y) is approximately (r,g,b). crengine fills solid
    -- colours exactly, but allow a small tolerance for any rounding on the
    -- same-size blit.
    local function assertPixel(bb, x, y, r, g, b, label)
        local c = bb:getPixel(x, y)
        local pr, pg, pb = c:getR(), c:getG(), c:getB()
        local tol = 20
        local ok = math.abs(pr - r) <= tol and math.abs(pg - g) <= tol and math.abs(pb - b) <= tol
        assert.is_true(ok, string.format(
            "%s at (%d,%d): expected ~(%d,%d,%d), got (%d,%d,%d)",
            label, x, y, r, g, b, pr, pg, pb))
    end

    it("places absolute boxes at their CSS coordinates", function()
        local doc, bb = render(1)

        -- #green: top band, full width (tests left:0/top:0 + width:100%).
        assertPixel(bb, 400, 20, 0x3b, 0xb0, 0x4e, "green top band")
        -- #red: anchored by top:100/left:50, 200x150 -> interior point (150,175).
        assertPixel(bb, 150, 175, 0xe6, 0x3b, 0x2e, "red box (top/left)")
        -- #inner: nested in #red at top:20/left:20 -> page (70..110, 120..160).
        assertPixel(bb, 90, 140, 0xe6, 0xc3, 0x2e, "nested box (relative to ancestor)")
        -- #blue: anchored by bottom:0/right:0, 120x90 -> interior point (740,1150).
        assertPixel(bb, 740, 1150, 0x2e, 0x8b, 0xe6, "blue box (bottom/right)")
        -- Empty centre stays the white page background.
        assertPixel(bb, 400, 600, 0xff, 0xff, 0xff, "white background")

        bb:free()
        doc:close()
    end)
end)
